import{z as s,x as o,o as t,c as d,q as r,j as l,D as e,d as B,s as n,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"欧拉序与森林维护","description":"","frontmatter":{"title":"欧拉序与森林维护","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/euler-tour-tree.md","filePath":"cs/euler-tour-tree.md","lastUpdated":1791063341000}'),u={name:"cs/euler-tour-tree.md"};function C(p,E,D,m,F,T){const A=o("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="欧拉序与森林维护" tabindex="-1">欧拉序与森林维护 <a class="header-anchor" href="#欧拉序与森林维护" aria-label="Permalink to &quot;欧拉序与森林维护&quot;">​</a></h1><div class="epigraph"><p>把整棵树绕一圈，进出各记一笔，森林就变成一条可以前后缝合的序列：子树是连续区间，断边与连边只是剪开再粘上。</p><footer>—— 据 Henzinger 与 King 的欧拉序树结构, 1995；全动态树算法综述</footer></div><p><a href="/cs/link-cut-tree">上一课</a>的 LCT 把任意路径拉直，路径聚合顺手，子树信息却是软肋——要给每个点养一份虚儿子之和。缺口在这：增删边照旧，主战场换成子树。办法是把树拍平成 <strong>欧拉序</strong>，用平衡树伺候这条序列。本课写欧拉序树（ETT），不写全动态二连通。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态子树和的标配是 DFS 序加 <a href="/cs/segment-tree">segment-tree</a>：子树对应连续区间。麻烦在 cut——一次断边让编号重排，区间全体搬家。LCT 补不了这一面（见上一课边界）。缺口：边增删照常跑，子树和、子树赋值、判连通都要快。本课不碰全动态图的最短路类算法，也不展开 LCT 与 ETT 拼合的混合结构。</p><p><span class="marginnote">术语翻译：Euler tour 通译「欧拉序」或「欧拉环游」，此处指 DFS 进入与离开各记一次的环游序（长 \\(2n\\)），不是图论里一笔画的那条欧拉回路——同一名词两个世界，别混。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环游序定义在有根树上：进入点记「入」，从子树回来记「出」，全程 \\(2n\\) 条记录。关键观察一：子树 \\(v\\) 恰是「\\(v\\) 的入」到「\\(v\\) 的出」这一段。关键观察二：把序列首尾接成环，link 与 cut 都只需搬小段——cut 删掉 \\(v\\) 的入出两条记录再把断口缝合，link 把 \\(u\\) 的子树段整体插到 \\(v\\) 的出点之前。用可分裂合并的平衡树（treap、splay 均可）维护。</p>',8)),(t(),l(i,null,{default:e(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%95%B4%E6%A3%B5%E6%A0%91%E7%9A%84%E6%AC%A7%E6%8B%89%E5%BA%8F%E5%AD%98%E5%9C%A8%E5%B9%B3%E8%A1%A1%E6%A0%91%E9%87%8C%22%5D%20--%3E%20B%7B%22%E6%9C%AC%E6%AC%A1%E6%93%8D%E4%BD%9C%E6%98%AF%E4%BB%80%E4%B9%88%22%7D%0A%20%20B%20--%3E%7C%22cut%20%E7%88%B6%E5%AD%90%E8%BE%B9%20u%20%E5%88%B0%20v%22%7C%20C%5B%22%E5%AE%9A%E4%BD%8D%20v%20%E7%9A%84%E5%85%A5%E4%B8%8E%E5%87%BA%E4%B8%A4%E6%9D%A1%E8%AE%B0%E5%BD%95%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%88%A0%E5%8E%BB%E4%B8%A4%E6%9D%A1%E8%AE%B0%E5%BD%95%EF%BC%8C%E6%96%AD%E5%8F%A3%E5%89%8D%E5%90%8E%E7%9B%B4%E6%8E%A5%E7%BC%9D%E5%90%88%22%5D%0A%20%20B%20--%3E%7C%22link%20u%20%E5%88%B0%20v%22%7C%20E%5B%22%E5%88%87%E5%87%BA%20u%20%E6%89%80%E5%9C%A8%E7%9A%84%E5%AD%90%E6%A0%91%E8%BF%9E%E7%BB%AD%E6%AE%B5%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%95%B4%E6%AE%B5%E6%8F%92%E5%88%B0%20v%20%E7%9A%84%E5%87%BA%E7%82%B9%E4%B9%8B%E5%89%8D%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"搬动成本是平衡树的分裂合并，\\(O(\\log n)\\) 级，与被搬子树的大小无关——这是与「重排整个 DFS 序」的本质区别。",-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"数字实例：\\(n=5\\) 的树环游序长 \\(10\\)；link 一棵 \\(3\\) 个点的子树，整段只搬 \\(2\\times 3=6\\) 条记录，分裂合并不超过二十步，全程与树高无关。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"为什么子树信息天然免费：环游序里子树就是一段区间，区间和、区间赋值、区间打标全是平衡树的看家菜。为什么 cut 只删两条：环上删两处、缝两针，环的拓扑不变。判连通也便宜：每棵树的环游序单独存一棵平衡树，比较两点所在树的标识即可。代价在同一枚硬币反面：路径和、路径最值在环游序上没有连续区间可用，ETT 反过来要借 LCT 的思路补——两种结构互为镜像。",-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"常见误区：把环游序写成只记进入的 DFS 序（长 \\(n\\)）。那样的序列里子树虽是区间，cut 却无法对称删除——错在省掉了「出」记录；进出成对，才保得住环上缝合的对称性。")],-1)),(t(),l(i,null,{default:e(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20L%5B%22LCT%22%5D%20--%3E%20LP%5B%22%E8%B7%AF%E5%BE%84%E5%92%8C%E4%B8%8E%E8%B7%AF%E5%BE%84%E8%B5%8B%E5%80%BC%EF%BC%9A%E5%BC%BA%E9%A1%B9%22%5D%0A%20%20L%20--%3E%20LS%5B%22%E5%AD%90%E6%A0%91%E5%92%8C%EF%BC%9A%E8%A6%81%E5%8F%A6%E5%85%BB%E8%99%9A%E5%84%BF%E5%AD%90%E4%BF%A1%E6%81%AF%22%5D%0A%20%20E%5B%22%E6%AC%A7%E6%8B%89%E5%BA%8F%E6%A0%91%22%5D%20--%3E%20ES%5B%22%E5%AD%90%E6%A0%91%E5%92%8C%E4%B8%8E%E8%B5%8B%E5%80%BC%EF%BC%9A%E5%8C%BA%E9%97%B4%E6%9F%A5%E8%AF%A2%EF%BC%8C%E7%99%BD%E9%80%81%22%5D%0A%20%20E%20--%3E%20EP%5B%22%E8%B7%AF%E5%BE%84%E8%81%9A%E5%90%88%EF%BC%9A%E5%BC%B1%E9%A1%B9%EF%BC%8C%E8%A6%81%E5%8F%A6%E9%85%8D%E7%BB%93%E6%9E%84%22%5D%0A%20%20LP%20--%3E%20P%5B%22%E9%80%89%E5%9E%8B%E5%85%88%E9%97%AE%EF%BC%9A%E5%8A%A8%E7%9A%84%E6%98%AF%E8%B7%AF%E5%BE%84%E8%BF%98%E6%98%AF%E5%AD%90%E6%A0%91%22%5D%0A%20%20EP%20--%3E%20P%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ETT 默认有根树，换根是它的另一个软肋；频繁换根回 LCT。点权挂在入出记录里随段搬动，边权信息进区间标记即可。判连通若高频，另配并查集只判不删更省。结构这一层到此换挡：下一课的对象干脆没有树形——一段数列，问题变成「哪条最短线性递推能生成它」。</p><p><span class="marginnote">直觉类比：环游序像巡更人绕楼一圈的打卡记录——进每个房间刷一次、出来再刷一次。封掉一条走廊（cut）只是撕掉两页打卡并粘上；把整个楼层挂到另一栋楼（link）是把那一沓记录整本插进新位置。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>环游序 \\(2n\\) 条记录，子树即区间，link/cut 即环上剪贴。</li><li>平衡树 split/merge 承担全部结构变动，单操作 \\(O(\\log n)\\)。</li><li>与 LCT 互为镜像：子树强则路径弱，选型看动哪一头。</li><li>出处：Henzinger 与 King, <em>Fully Dynamic Biconnectivity in Graphs</em>, Algorithmica 1999（欧拉序树结构）；对照 Tarjan 与 Vishkin 的动态树工作。</li></ul>',5))])}const f=s(u,[["render",C]]);export{h as __pageData,f as default};
